<div class="page-header"><div><h1 class="h3">Reports</h1><p class="text-muted mb-0">Server-generated reports from actual expense data.</p></div><?php if(can('reports.export')):?><a class="action-button action-button--primary btn btn-outline-primary" href="<?=url('reports/csv?'.http_build_query($f))?>"><i data-feather="download" aria-hidden="true"></i>Export CSV</a><?php endif;?></div><div class="card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-3"><select class="form-select" name="category_id"><option value="" data-icon="layers">All Categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" data-icon="<?=e($c['display_icon'] ?? $c['icon'] ?? 'tag')?>" <?=selected($f['category_id']??'',$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="account_id"><option value="" data-icon="briefcase">All Accounts</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" data-account-type="<?=e($a['type'] ?? '')?>" <?=selected($f['account_id']??'',$a['id'])?>><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="date" name="from" value="<?=e($f['from']??'')?>"></div><div class="col-md-2"><input class="form-control" type="date" name="to" value="<?=e($f['to']??'')?>"></div><div class="col-md-2"><button class="action-button action-button--primary btn btn-primary w-100"><i data-feather="filter" aria-hidden="true"></i>Apply</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Amount</th><th>Category</th><th>Account</th><th>Description</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(display_date($r['expense_date']))?></td><td><?=money($r['amount'])?></td><td><?=category_label($r['category'] ?? '', $r['category_icon'] ?? null, $r['category_color'] ?? null, $r['badge'] ?? null)?></td><td><?=account_type_label($r['account_type'] ?? '', $r['account'] ?? null)?></td><td><?=e($r['description'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>
